//! A small FIFO job queue.
pub mod metrics;
pub mod scheduler;
pub mod worker;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Job {
    pub name: String,
    pub priority: u8,
}

impl Job {
    pub fn new(name: impl Into<String>, priority: u8) -> Self {
        Self { name: name.into(), priority }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Queue {
    jobs: Vec<Job>,
}

impl Queue {
    pub fn new() -> Self {
        Self { jobs: Vec::new() }
    }

    pub fn submit(&mut self, job: Job) {
        self.jobs.push(job);
    }

    pub fn drain(&mut self) -> Vec<Job> {
        std::mem::take(&mut self.jobs)
    }

    pub fn len(&self) -> usize {
        self.jobs.len()
    }
}

//! Warmup + processing worker.
use crate::{Job, Queue};

pub fn process_all(queue: &mut Queue) -> Vec<Job> {
    queue.submit(Job::new("warmup", 0));
    queue.drain()
}

//! Batch scheduling.
use crate::{Job, Queue};

pub fn enqueue_batch(queue: &mut Queue, names: &[&str]) {
    for name in names {
        queue.submit(Job::new(*name, 0));
    }
}

//! Queue metrics.
use crate::Queue;

pub fn pending(queue: &Queue) -> usize {
    queue.len()
}

//! Typed FIFO queue coverage.
use taskqueue::{Job, Queue};

#[test]
fn fifo_order_is_preserved() {
    let mut queue = Queue::new();
    queue.submit(Job::new("a", 1));
    queue.submit(Job::new("b", 2));
    assert_eq!(queue.drain(), vec![Job::new("a", 1), Job::new("b", 2)]);
    assert_eq!(queue.drain(), Vec::new());
    assert_eq!(queue.len(), 0);
}

